/**
 * @return pair with left value as inputs and right value as outputs,
 *  passed in current call to authorizer.checkPrivileges
 * @throws HiveAuthzPluginException
 * @throws HiveAccessControlException
 */
private Pair<List<HivePrivilegeObject>, List<HivePrivilegeObject>> getHivePrivilegeObjectInputs() throws HiveAuthzPluginException, HiveAccessControlException {
    // Create argument capturer
    // a class variable cast to this generic of generic class
    Class<List<HivePrivilegeObject>> class_listPrivObjects = (Class) List.class;
    ArgumentCaptor<List<HivePrivilegeObject>> inputsCapturer = ArgumentCaptor.forClass(class_listPrivObjects);
    ArgumentCaptor<List<HivePrivilegeObject>> outputsCapturer = ArgumentCaptor.forClass(class_listPrivObjects);
    verify(mockedAuthorizer).checkPrivileges(any(HiveOperationType.class), inputsCapturer.capture(), outputsCapturer.capture(), any(HiveAuthzContext.class));
    return new ImmutablePair(inputsCapturer.getValue(), outputsCapturer.getValue());
}

@Override
public HiveAuthorizer createHiveAuthorizer(HiveMetastoreClientFactory metastoreClientFactory, HiveConf conf, HiveAuthenticationProvider authenticator, HiveAuthzSessionContext ctx) {
    Mockito.validateMockitoUsage();
    abstract class AuthorizerWithFilterCmdImpl implements HiveAuthorizer {

        @Override
        public List<HivePrivilegeObject> filterListCmdObjects(List<HivePrivilegeObject> listObjs, HiveAuthzContext context) throws HiveAuthzPluginException, HiveAccessControlException {
            // capture arguments in static
            filterArguments = listObjs;
            // return static variable with results, if it is set to some set of
            // values
            // otherwise return the arguments
            if (filteredResults.size() == 0) {
                return filterArguments;
            }
            return filteredResults;
        }
    }
    mockedAuthorizer = Mockito.mock(AuthorizerWithFilterCmdImpl.class, Mockito.withSettings().verboseLogging());
    try {
        Mockito.when(mockedAuthorizer.filterListCmdObjects((List<HivePrivilegeObject>) any(), (HiveAuthzContext) any())).thenCallRealMethod();
    } catch (Exception e) {
        org.junit.Assert.fail("Caught exception " + e);
    }
    return mockedAuthorizer;
}

