    assertEquals(1, requestManager.numSubmissionsCounters);
    assertNotNull(requestManager.numInvocationsPerNode.get(nodeId1));
    assertEquals(1, requestManager.numInvocationsPerNode.get(nodeId1).getValue().intValue());
